        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/nodes/{node}/apt/update"
        public static let schemaName = "update_database"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        /// Send notification about new packages.
        ///
        /// Default: `0`.
        public var notify: Bool?

        /// Only produces output suitable for logging, omitting progress indicators.
        ///
        /// Default: `0`.
        public var quiet: Bool?

        public init(node: String) {
            self.node = node
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "apt", "update") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = notify { result.append(("notify", value.parameterValue)) }
            if let value = quiet { result.append(("quiet", value.parameterValue)) }
            return result
        }
    }

    /// `GET /nodes/{node}/apt/update-changelogs`
    ///
    /// Get the changelog entries for pending updates, grouped by source package.
    public struct GetNodesAptUpdateChangelogs: PVEAPIRequest, Hashable {
        public typealias Response = [Item]
        public static let method: HTTPMethod = .get
        public static let pathTemplate = "/nodes/{node}/apt/update-changelogs"
        public static let schemaName = "update_changelogs"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        public init(node: String) {
            self.node = node
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "apt", "update-changelogs") }

        public var parameters: [(String, String)] { [] }

        public struct Item: Decodable, Sendable, Hashable {
            /// The entries of the versions that upgrades and downgrades changed between, for other changes only the newest one up to the new version, usually newest first.
            public var entries: [EntriesItem]?
            /// Why the changelog could not be read.
            public var error: String?
            /// The changes to binary packages of the source package that show these entries.
            public var packages: [PackagesItem]?
            /// Name of the source package as its changelog lists it, or as APT names it for a changelog that could not be downloaded. Missing if no changelog is installed for the packages, or the source package is not known.
            public var source: String?
            /// The changelog does not list the version the entries go up to, as for signed kernels, so the entries are only its newest one, which can belong to a later version.
            public var unlistedVersion: Bool?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                entries = try? c.decodeIfPresent([EntriesItem].self, forKey: AnyCodingKey("entries"))
                error = c.flexibleString(AnyCodingKey("error"))
                packages = try? c.decodeIfPresent([PackagesItem].self, forKey: AnyCodingKey("packages"))
                source = c.flexibleString(AnyCodingKey("source"))
                unlistedVersion = c.flexibleBool(AnyCodingKey("unlisted-version"))
            }

            public struct EntriesItem: Decodable, Sendable, Hashable {
                /// The changes as written in the changelog, usually as an indented list.
                public var changes: String?
                /// Date of the entry as written in the changelog.
                public var date: String?
                /// Distributions the version was uploaded to, separated by spaces.
                public var distributions: String?
                /// Name and email address of the author of the entry.
                public var maintainer: String?
                /// Name of the source package.
                public var package: String?
                /// Urgency of the upload.
                public var urgency: String?
                /// Version of the source package.
                public var version: String?

                public init(from decoder: any Decoder) throws {
                    let c = try decoder.container(keyedBy: AnyCodingKey.self)
                    changes = c.flexibleString(AnyCodingKey("changes"))
                    date = c.flexibleString(AnyCodingKey("date"))
                    distributions = c.flexibleString(AnyCodingKey("distributions"))
                    maintainer = c.flexibleString(AnyCodingKey("maintainer"))
                    package = c.flexibleString(AnyCodingKey("package"))
                    urgency = c.flexibleString(AnyCodingKey("urgency"))
                    version = c.flexibleString(AnyCodingKey("version"))
                }
            }

            public struct PackagesItem: Decodable, Sendable, Hashable {
                /// What the transaction did to the package.
                public var action: String?
                /// Package architecture.
                public var arch: String?
                /// Whether APT marked the newly installed package as installed automatically.
                public var automatic: Bool?
                /// Version installed by the transaction.
                public var newVersion: String?
                /// Version installed before the transaction.
                public var oldVersion: String?
                /// Package name.
                public var package: String?

                public init(from decoder: any Decoder) throws {
                    let c = try decoder.container(keyedBy: AnyCodingKey.self)
                    action = c.flexibleString(AnyCodingKey("action"))
                    arch = c.flexibleString(AnyCodingKey("arch"))
                    automatic = c.flexibleBool(AnyCodingKey("automatic"))
                    newVersion = c.flexibleString(AnyCodingKey("new-version"))
                    oldVersion = c.flexibleString(AnyCodingKey("old-version"))
                    package = c.flexibleString(AnyCodingKey("package"))
                }
            }
        }
    }

    /// `GET /nodes/{node}/apt/versions`
    ///
    /// Get package information for important Proxmox packages.
    public struct GetNodesAptVersions: PVEAPIRequest, Hashable {
        public typealias Response = [Item]
        public static let method: HTTPMethod = .get
        public static let pathTemplate = "/nodes/{node}/apt/versions"
        public static let schemaName = "versions"

        /// The cluster node name.
        ///
        /// Format: `pve-node`.
        public var node: String

        public init(node: String) {
            self.node = node
        }

        public var path: String { PathBuilder.path("nodes", node.parameterValue, "apt", "versions") }

        public var parameters: [(String, String)] { [] }

        public struct Item: Decodable, Sendable, Hashable {
            /// Package Architecture.
            public var arch: String?
            /// Current state of the package installed on the system.
