            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                arch = c.flexibleString(AnyCodingKey("Arch"))
                currentState = c.flexibleString(AnyCodingKey("CurrentState"))
                description = c.flexibleString(AnyCodingKey("Description"))
                managerVersion = c.flexibleString(AnyCodingKey("ManagerVersion"))
                notifyStatus = c.flexibleString(AnyCodingKey("NotifyStatus"))
                oldVersion = c.flexibleString(AnyCodingKey("OldVersion"))
                origin = c.flexibleString(AnyCodingKey("Origin"))
                package = c.flexibleString(AnyCodingKey("Package"))
                priority = c.flexibleString(AnyCodingKey("Priority"))
                runningKernel = c.flexibleString(AnyCodingKey("RunningKernel"))
                section = c.flexibleString(AnyCodingKey("Section"))
                title = c.flexibleString(AnyCodingKey("Title"))
                version = c.flexibleString(AnyCodingKey("Version"))
            }
        }
    }
